import{_ as a,o,c as t,a2 as r}from"./chunks/framework.CqGPl1zp.js";const c="/newx-doc/assets/API%E5%AF%86%E9%92%A5.7_Wvb_kO.png",n="/newx-doc/assets/%E6%A8%A1%E5%9E%8B%E9%85%8D%E7%BD%AE.D6PO4qiZ.png",p="/newx-doc/assets/AI%E5%AF%B9%E8%AF%9D.e_PG5b6f.png",f=JSON.parse('{"title":"Coze 智能体","description":"","frontmatter":{},"headers":[],"relativePath":"ai/coze.md","filePath":"ai/coze.md","lastUpdated":null}'),l={name:"ai/coze.md"};function h(i,e,s,d,_,A){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="coze-智能体" tabindex="-1">Coze 智能体 <a class="header-anchor" href="#coze-智能体" aria-label="Permalink to &quot;Coze 智能体&quot;">​</a></h1><h2 id="_1-coze-是什么" tabindex="-1">1. Coze 是什么？ <a class="header-anchor" href="#_1-coze-是什么" aria-label="Permalink to &quot;1. Coze 是什么？&quot;">​</a></h2><p>Coze（中文名：扣子）是新一代 AI 应用开发平台。无论你是否有编程基础，都可以在扣子上快速搭建基于大模型的各类 AI 应用（智能体），并将 AI 应用发布到各个社交平台、通讯软件，也可以通过 API 或 SDK 将 AI 应用集成到你的业务系统中。</p><p>详细介绍，可见 <a href="https://www.coze.cn/open/docs/guides/welcome" target="_blank" rel="noreferrer">《什么是扣子》</a></p><ul><li>国内地址：<a href="https://www.coze.cn/" target="_blank" rel="noreferrer">https://www.coze.cn/</a></li><li>国外地址：<a href="https://www.coze.com/" target="_blank" rel="noreferrer">https://www.coze.com/</a></li></ul><h2 id="_2-如何接入" tabindex="-1">2. 如何接入？ <a class="header-anchor" href="#_2-如何接入" aria-label="Permalink to &quot;2. 如何接入？&quot;">​</a></h2><p>由于 Coze 的 <a href="https://www.coze.cn/open/playground/chat_v3" target="_blank" rel="noreferrer">对话接口</a> 不兼容 GPT 的接口，所以无法使用 <a href="./openai">《【模型接入】OpenAI》</a> 的方式，无法通过 OpenAIChatModel 进行接入。</p><p>不过，社区里有人提供了 <a href="https://github.com/fatwang2/coze2openai" target="_blank" rel="noreferrer">https://github.com/fatwang2/coze2openai</a> 项目，可以将 Coze 的对话接口转换为 OpenAI 的接口，这样就可以使用 OpenAIChatModel 进行接入了。</p><p>下面，我们讲解下，如何把我们系统中的 <a href="./chat">《AI 对话聊天》</a> ，接入到 Coze 智能体（Agent）。</p><h3 id="_2-1-第一步-创建-coze-智能体" tabindex="-1">2.1 第一步：创建 Coze 智能体 <a class="header-anchor" href="#_2-1-第一步-创建-coze-智能体" aria-label="Permalink to &quot;2.1 第一步：创建 Coze 智能体&quot;">​</a></h3><p>参考 《coze.cn 申请 API 使用流程》 文档，创建并发布一个 Coze 智能体。</p><p>整个过程中，重点是获取到智能体的 <code>BOT_ID</code>、和 API 的 <code>API_KEY</code>。</p><h3 id="_2-2-第二步-配置-api-密钥与模型" tabindex="-1">2.2 第二步：配置 API 密钥与模型 <a class="header-anchor" href="#_2-2-第二步-配置-api-密钥与模型" aria-label="Permalink to &quot;2.2 第二步：配置 API 密钥与模型&quot;">​</a></h3><p>〇 本地搭建 <a href="https://github.com/fatwang2/coze2openai" target="_blank" rel="noreferrer">https://github.com/fatwang2/coze2openai</a> 项目，将 Coze 的对话接口转换为 OpenAI 的接口。</p><p>在修改 <code>.env</code> 配置文件的时候要注意，一方面要修改 <code>BOT_ID</code>，另一方面要注意 <code>COZE_API_BASE</code> 改成 <code>api.coze.cn</code>！！！（我一开始，就踩坑一直跑不通。。。）</p><p>① 在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; API 密钥] 菜单，新建一个 Coze 的 API 密钥，填写上面的“密钥”，并设置 URL 为 <code>http://127.0.0.1:3000</code> 。如下图所示：</p><p><img src="'+c+'" alt="API 密钥"></p><p>② 在我们系统的 [AI 大模型 -&gt; 控制台 -&gt; 模型配置] 菜单，新建一个 Coze 的聊天模型，填写上面的“模型名称” + “API 密钥” + “API URL”。如下图所示：</p><p><img src="'+n+'" alt="模型配置"></p><h3 id="_2-3-第三步-ai-对话聊天" tabindex="-1">2.3 第三步：AI 对话聊天 <a class="header-anchor" href="#_2-3-第三步-ai-对话聊天" aria-label="Permalink to &quot;2.3 第三步：AI 对话聊天&quot;">​</a></h3><p>在 [AI 大模型 -&gt; AI 对话] 菜单，选择 Coze 的聊天模型，即可开始对话。如下图所示：</p><p><img src="'+p+'" alt="AI 对话"></p><h2 id="_3-常见问题" tabindex="-1">3. 常见问题？ <a class="header-anchor" href="#_3-常见问题" aria-label="Permalink to &quot;3. 常见问题？&quot;">​</a></h2><p>① 如果你想使用 Coze 知识库接口，可参考 <a href="https://www.coze.cn/open/playground/create_dataset" target="_blank" rel="noreferrer">https://www.coze.cn/open/playground/create_dataset</a> 进行对接。</p><p>当然，我们系统已经提供了 <a href="./knowledge">《AI 知识库》</a> 功能。</p>',25)])])}const I=a(l,[["render",h]]);export{f as __pageData,I as default};
